func:
// modbus-flex-sequencer drops custom msg properties, so the snapshot lives in flow context.
// Cycles never overlap: if a snapshot is still in flight (< 25 s old) this inject is skipped, so a
// slow cycle's late Stash/Build calls can never hit the next cycle's snapshot. A failed read (empty payload)
// clears the snapshot in Stash; otherwise it expires after 25 s.
const MAX_CYCLE_MS = 25000;
const c = flow.get("hp_cycle");
if (c && Number.isFinite(c.ts) && Date.now() - c.ts < MAX_CYCLE_MS && Date.now() >= c.ts) {
  node.warn("heat_pump: previous cycle still in flight, inject skipped");
  return null;
}
flow.set("hp_cycle", { ts: Date.now(), lg: {} });   // ts = read start time, used as the payload ts
msg.payload = true;
return msg;

// FC4 input regs 0..13. A failed read never reaches here (error output unwired); also reject malformed payloads.
// Registers are not padded: exact length.
const p = msg.payload;
if (!(Array.isArray(p) && p.length === 14)) { flow.set("hp_cycle", undefined); node.warn("heat_pump: bad input0 block, cycle dropped"); return null; }
const c = flow.get("hp_cycle");
if (!c || !c.lg) { node.warn("heat_pump: input0 without a cycle snapshot, dropped"); return null; }
c.lg.input0 = p.slice(0, 14);
flow.set("hp_cycle", c);
msg.payload = true;
return msg;

// FC4 input regs 16..24. A failed read never reaches here (error output unwired); also reject malformed payloads.
// Registers are not padded: exact length.
const p = msg.payload;
if (!(Array.isArray(p) && p.length === 9)) { flow.set("hp_cycle", undefined); node.warn("heat_pump: bad input16 block, cycle dropped"); return null; }
const c = flow.get("hp_cycle");
if (!c || !c.lg) { node.warn("heat_pump: input16 without a cycle snapshot, dropped"); return null; }
c.lg.input16 = p.slice(0, 9);
flow.set("hp_cycle", c);
msg.payload = true;
return msg;

// FC2 discrete inputs 0..13. A failed read never reaches here (error output unwired); also reject malformed payloads.
// FC2 replies are padded to whole bytes (quantity 14 returns 16 booleans): accept >= 14, keep the first 14.
const p = msg.payload;
if (!(Array.isArray(p) && p.length >= 14)) { flow.set("hp_cycle", undefined); node.warn("heat_pump: bad discrete0 block, cycle dropped"); return null; }
const c = flow.get("hp_cycle");
if (!c || !c.lg) { node.warn("heat_pump: discrete0 without a cycle snapshot, dropped"); return null; }
c.lg.discrete0 = p.slice(0, 14);
flow.set("hp_cycle", c);
msg.payload = true;
return msg;

// Holding regs 0..9 arrive in msg.payload; earlier blocks were stashed in flow context "hp_cycle".
// Missing/short block, or missing/stale snapshot => publish nothing (never a partial snapshot).

const MAX_CYCLE_MS = 25000;   // in-flight cycles never overlap (Start skips); an older snapshot is stale
const put = (m, k, v) => { if (typeof v === "number" && Number.isFinite(v)) m[k] = v; };

const s16 = v => (v >= 32768 ? v - 65536 : v);
const id = v => v, flag = v => (v ? 1 : 0), div10 = v => v / 10, div100 = v => v / 100;
// int16 /10 degC; raw 64887 = -64.9 is the "sensor not connected" sentinel => omit anything <= -60
const temp = v => { const t = s16(v) / 10; return t <= -60 ? undefined : t; };
const LEN = { input0: 14, input16: 9, discrete0: 14, holding: 10 };
// [block, index, metric, decoder]; index is relative to the block start (input16 starts at reg 16)
const MAP = [
  ["input0", 0, "error_code", id], ["input0", 1, "odu_cycle", id], ["input0", 2, "return_temp", temp],
  ["input0", 3, "flow_temp", temp], ["input0", 5, "dhw_temp", temp], ["input0", 7, "room_temp", temp],
  ["input0", 8, "flow_rate", v => v * 6],   // raw 0.1 L/min -> L/h
  ["input0", 11, "energy_state", id], ["input0", 12, "outdoor_temp", temp],
  ["input16", 0, "liquid_temp", temp], ["input16", 2, "suction_temp", temp], ["input16", 3, "discharge_temp", temp],
  ["input16", 4, "evaporator_in_temp", temp], ["input16", 5, "evaporator_out_temp", temp],
  ["input16", 6, "high_pressure", div100], ["input16", 7, "low_pressure", div100], ["input16", 8, "compressor_hz", id],
  ["discrete0", 1, "water_pump_on", flag], ["discrete0", 3, "compressor_on", flag], ["discrete0", 4, "defrost_active", flag],
  ["discrete0", 5, "dhw_active", flag], ["discrete0", 6, "dhw_disinfection_active", flag], ["discrete0", 7, "silent_mode", flag],
  ["discrete0", 10, "backup_heater_1_on", flag], ["discrete0", 11, "backup_heater_2_on", flag],
  ["discrete0", 12, "dhw_heater_on", flag], ["discrete0", 13, "error_active", flag],
  ["holding", 0, "mode_setting", id], ["holding", 1, "control_method", id], ["holding", 2, "target_flow_temp", div10],
  ["holding", 4, "curve_shift", s16], ["holding", 8, "dhw_target_temp", div10],
];
const c = flow.get("hp_cycle");
flow.set("hp_cycle", undefined);   // consume: a snapshot is published at most once
if (!c || !Number.isFinite(c.ts) || Date.now() - c.ts > MAX_CYCLE_MS || Date.now() < c.ts) {
  node.warn("heat_pump: no fresh cycle snapshot, nothing published");
  return null;
}
const blocks = Object.assign({}, c.lg, { holding: msg.payload });
for (const k of Object.keys(LEN)) {
  if (!Array.isArray(blocks[k]) || blocks[k].length !== LEN[k]) {
    node.warn("heat_pump: incomplete snapshot (" + k + "), nothing published");
    return null;
  }
}
const metrics = {};
for (const [block, i, name, decode] of MAP) put(metrics, name, decode(blocks[block][i]));
const ts = new Date(c.ts).toISOString();

if (Object.keys(metrics).length === 0) { node.warn("heat_pump: no valid metrics, nothing published"); return null; }
return { payload: JSON.stringify({ ts, metrics }) };

// modbus-flex-sequencer drops custom msg properties: keep the read start time in flow context.
// Cycles never overlap: skip while a read started < 25 s ago is still in flight (failures clear em_ts).
const t0 = flow.get("em_ts");
if (Number.isFinite(t0) && Date.now() - t0 < 25000 && Date.now() >= t0) {
  node.warn("electricity_meter: previous read still in flight, inject skipped");
  return null;
}
flow.set("em_ts", Date.now());
msg.payload = true;
return msg;

// Eastron SDM220: float32, big-endian word order (high word first), input regs.

const MAX_CYCLE_MS = 25000;   // in-flight cycles never overlap (Start skips); an older snapshot is stale
const put = (m, k, v) => { if (typeof v === "number" && Number.isFinite(v)) m[k] = v; };

const t0 = flow.get("em_ts");
flow.set("em_ts", undefined);   // consume
if (!Number.isFinite(t0) || Date.now() - t0 > MAX_CYCLE_MS || Date.now() < t0) {
  node.warn("electricity_meter: no fresh read start time, nothing published");
  return null;
}
const ts = new Date(t0).toISOString();
const p = msg.payload;
if (!Array.isArray(p) || p.length < 80) { node.warn("electricity_meter: bad block, nothing published"); return null; }
const round = (v, dp) => { const f = Math.pow(10, dp); return Math.round(v * f) / f; };
const f32 = r => {
  const buf = Buffer.alloc(4);
  buf.writeUInt16BE(p[r], 0);
  buf.writeUInt16BE(p[r + 1], 2);
  return buf.readFloatBE(0);
};
const metrics = {};
try {
  put(metrics, "voltage", round(f32(0), 2));             // V
  put(metrics, "current", round(f32(6), 3));             // A
  put(metrics, "power_w", round(f32(12), 2));            // W
  put(metrics, "power_factor", round(f32(30), 3));
  put(metrics, "energy_kwh", round(f32(72), 3));         // import active energy, kWh
} catch (e) { node.warn("electricity_meter: bad register value, nothing published"); return null; }

if (Object.keys(metrics).length === 0) { node.warn("electricity_meter: no valid metrics, nothing published"); return null; }
return { payload: JSON.stringify({ ts, metrics }) };

// Kamstrup Multical via M-Bus. Match DataRecord entries by StorageNumber 0 + "Instantaneous value" + Unit text,
// never by array index. ts = read time (Date.now() when the reply arrives); the meter's own record
// Timestamp is deliberately ignored (meter clock may be off; SQL relies on real sample spacing).
let pl = msg.payload;
if (typeof pl === "string") { try { pl = JSON.parse(pl); } catch (e) { pl = null; } }
const recs = pl && Array.isArray(pl.DataRecord) ? pl.DataRecord : null;
if (!recs) { node.warn("heat_meter: no DataRecord, nothing published"); return null; }
const ts = new Date(Date.now()).toISOString();
// quantity (Unit text before the parenthesis) -> metric and per-unit factor [mul, div] to the metric unit
const QTY = {
  "Energy": ["energy_kwh", { "Wh": [1, 1000], "kWh": [1, 1], "MWh": [1000, 1] }],
  "Volume": ["volume_m3", { "m^3": [1, 1] }],
  "Flow temperature": ["flow_temp", { "deg C": [1, 1] }],
  "Return temperature": ["return_temp", { "deg C": [1, 1] }],
  "Power": ["power_w", { "W": [1, 1], "kW": [1000, 1] }],
  "Volume flow": ["flow_rate", { "m^3/h": [1000, 1] }]   // m3/h -> L/h
};
const metrics = {};
for (const r of recs) {
  if (!r || r.StorageNumber !== 0 || String(r.Function).trim() !== "Instantaneous value") continue;
  const m = /^\s*(.+?)\s*\(\s*(.*?)\s*\)\s*$/.exec(String(r.Unit));
  const q = m && QTY[m[1].replace(/\s+/g, " ")];
  if (!q || Object.prototype.hasOwnProperty.call(metrics, q[0])) continue;
  const tok = m[2].split(/\s+/).filter(Boolean);
  let mul = 1, div = 1;
  if (tok.length > 1 && /^(1e-?\d+|\d+)$/.test(tok[0])) {          // decimal multiplier, e.g. "1e-2", "100"
    const n = Number(tok.shift());
    if (n < 1) div *= Math.round(1 / n); else mul *= n;
  }
  if (tok.length > 1 && tok[0] === "m") { tok.shift(); div *= 1000; } // milli prefix, e.g. "m m^3/h"
  const uf = q[1][tok.join(" ")];
  const v = Number(r.Value);
  if (!uf || r.Value === null || r.Value === "" || !Number.isFinite(v)) continue;
  metrics[q[0]] = Number((v * mul / div * uf[0] / uf[1]).toPrecision(12));
}

if (Object.keys(metrics).length === 0) { node.warn("heat_meter: no valid metrics, nothing published"); return null; }
return { payload: JSON.stringify({ ts, metrics }) };
